#[test]
fn certora_39657_reduction_publishes_a_confirmed_sat() {
    let commands = parse(CERTORA_39657_REDUCED).expect("valid SMT-LIB test input");
    let mut executor = Executor::new();
    let output = executor
        .execute_all(&commands)
        .expect("commands must execute");
    let verdict = output
        .iter()
        .rev()
        .map(|line| line.trim())
        .find(|line| matches!(*line, "sat" | "unsat" | "unknown"))
        .unwrap_or_default();
    assert_eq!(verdict, "sat", "output: {output:?}");
    assert_eq!(
        executor
            .statistics()
            .get_string("model_check_gate.result")
            .map(str::to_owned),
        Some("confirmed-sat".to_string()),
        "the published sat must carry the independent gate's confirmation"
    );
}
